        crossover_points = [(random.randint(1, len(genes) - 1) for _ in range(len(genes)))]

    for i, gene in enumerate(genes):
        for points in crossover_points:
            if i < points[i % len(points)]:
                child_chromo[gene] = parent1_chromo[gene]
            else:
                child_chromo[gene] = parent2_chromo[gene]

            # Introduce variation by choosing from both parents
            if random.random() < 0.5:
                child_chromo[gene] = self._coerce_gene_value(gene, random.choice([parent1_chromo[gene], parent2_chromo[gene]]))

            # Apply mutations during crossover to introduce diversity
            if random.random() < self.mutation_rate:
                child_chromo[gene] = self.mutate_gene(gene, child_chromo[gene], self.search_space[gene])

    return self._sanitize_chromosome(child_chromo)
